select client_id, app_id, app_secret, app_name, status, create_time from spas_open_client
and app_id like concat('%', #{appId,jdbcType=VARCHAR}, '%') and app_name like concat('%', #{appName,jdbcType=VARCHAR}, '%') and status = #{status}
order by client_id desc

mapper.update:
update spas_open_client
app_id = #{appId}, app_secret = #{appSecret}, app_name = #{appName}, status = #{status},
where client_id = #{clientId}

mapper.select:
